@push('styles')
<style>
.iv{color:#334155;max-width:1600px;margin:auto}.iv *{box-sizing:border-box}.iv h2{font-size:24px;font-weight:750;color:#0f172a}.iv h3{font-size:17px;font-weight:700;color:#0f172a;margin-bottom:12px}.iv-head{display:flex;gap:14px;align-items:center;justify-content:space-between;flex-wrap:wrap;margin-bottom:18px}.iv-muted{font-size:12px;color:#64748b}.iv-card{padding:20px;background:white;border:1px solid #e2e8f0;border-radius:12px;margin-bottom:20px}.iv-info{padding:12px 15px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;font-size:12px;color:#1e40af;margin:12px 0}.iv-warn{background:#fffbeb;border-color:#fde68a;color:#92400e}.iv-badge{background:#dbeafe;color:#1e40af;border-radius:24px;padding:6px 12px;font-size:12px;font-weight:600}.iv-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}.iv-btn{display:inline-block;border:1px solid #cbd5e1;border-radius:7px;padding:9px 13px;color:#334155;background:#fff;text-decoration:none;font-size:13px;font-weight:600;cursor:pointer}.iv-active{background:#2563eb;color:#fff;border-color:#2563eb}.iv-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:16px 0}.iv-stat{background:#f8fafc;border:1px solid #e2e8f0;border-radius:9px;padding:16px}.iv-stat strong{font-size:23px;display:block;color:#0f172a;overflow-wrap:anywhere}.iv-stat small{font-size:12px;color:#64748b}.iv-filter{display:flex;gap:12px;align-items:flex-end;flex-wrap:wrap;margin:15px 0}.iv-filter label{font-size:12px;color:#475569;display:block;flex:1;min-width:130px}.iv-filter input,.iv-filter select{display:block;width:100%;background:#fff;padding:9px 10px;border:1px solid #cbd5e1;border-radius:7px;margin-top:5px;font-size:13px;color:#0f172a}.iv-scroll{overflow-x:auto}.iv table{border-collapse:collapse;width:100%;font-size:12px;min-width:1050px}.iv th{background:#f8fafc;color:#64748b;text-align:left;padding:11px;border-bottom:1px solid #cbd5e1;white-space:nowrap}.iv td{padding:12px 11px;border-bottom:1px solid #e2e8f0;vertical-align:top}.iv td small{display:block;font-size:11px;color:#64748b;margin-top:3px}.iv a.iv-link{color:#2563eb;text-decoration:underline}.iv .num{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}.iv .positive{color:#047857}.iv .negative{color:#b91c1c}.iv details summary{cursor:pointer;color:#2563eb}.iv details p{max-width:300px;white-space:pre-wrap;overflow-wrap:anywhere;margin-top:8px}.iv .empty{text-align:center;padding:30px;color:#94a3b8}.iv-errors{padding:14px;background:#fef2f2;color:#991b1b;border-radius:8px;margin-bottom:15px}@media(max-width:900px){.iv-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:520px){.iv-grid{grid-template-columns:1fr}.iv-card{padding:15px}.iv-filter label{min-width:100%}}
</style>
@endpush
